{"explanation":"Add role-based access model with separate superuser/admin grants and admin-only download permission helpers.","input":"*** Begin Patch
*** Update File: d:\创业\睿思国际\網站\secure-portal\app.js
@@
   rewardsWallet: 'portal_rewards_wallet_v1',
   referrals: 'portal_referral_leads_v1',
   orders: 'portal_service_orders_v1',
-  serviceCatalog: 'portal_service_catalog_v1'
+  serviceCatalog: 'portal_service_catalog_v1',
+  roleGrants: 'portal_role_grants_v1'
 };
@@
 const SUPERUSER_EMAILS = ['superuser@cogniplatform.com'];
+const ROLE_TYPES = {
+  superuser: 'superuser',
+  admin: 'admin'
+};
@@
 function isSuperuser(email) {
-  return SUPERUSER_EMAILS.includes(normalizeEmail(email));
+  const normalized = normalizeEmail(email);
+  const grants = loadRoleGrants();
+  return grants.superusers.includes(normalized);
 }
+
+function isAdmin(email) {
+  const normalized = normalizeEmail(email);
+  const grants = loadRoleGrants();
+  return grants.admins.includes(normalized);
+}
+
+function canDownloadUserData(email) {
+  return isAdmin(email);
+}
+
+function loadRoleGrants() {
+  const seedSuperusers = Array.from(new Set(SUPERUSER_EMAILS.map((email) => normalizeEmail(email))));
+  const fallback = {
+    superusers: seedSuperusers,
+    admins: []
+  };
+
+  const raw = localStorage.getItem(KEYS.roleGrants);
+  if (!raw) {
+    return fallback;
+  }
+
+  try {
+    const parsed = JSON.parse(raw);
+    const superusers = Array.from(
+      new Set([...(Array.isArray(parsed.superusers) ? parsed.superusers : []), ...seedSuperusers].map((email) => normalizeEmail(email)).filter(Boolean))
+    );
+    const admins = Array.from(
+      new Set((Array.isArray(parsed.admins) ? parsed.admins : []).map((email) => normalizeEmail(email)).filter(Boolean))
+    );
+
+    return {
+      superusers,
+      admins
+    };
+  } catch {
+    return fallback;
+  }
+}
+
+function saveRoleGrants(grants) {
+  const normalized = {
+    superusers: Array.from(new Set((grants.superusers || []).map((email) => normalizeEmail(email)).filter(Boolean))),
+    admins: Array.from(new Set((grants.admins || []).map((email) => normalizeEmail(email)).filter(Boolean)))
+  };
+  localStorage.setItem(KEYS.roleGrants, JSON.stringify(normalized));
+}
+
+function getAssignableUsers() {
+  const enterprise = loadList(KEYS.approved).map((user) => ({
+    email: normalizeEmail(user.email),
+    fullName: user.fullName,
+    company: user.company,
+    source: 'enterprise'
+  }));
+  const manufacturer = loadList(KEYS.mApproved).map((user) => ({
+    email: normalizeEmail(user.email),
+    fullName: user.fullName,
+    company: user.company,
+    source: 'manufacturer'
+  }));
+
+  const merged = [...enterprise, ...manufacturer];
+  const map = new Map();
+  merged.forEach((user) => {
+    if (user.email && !map.has(user.email)) {
+      map.set(user.email, user);
+    }
+  });
+
+  return Array.from(map.values()).sort((a, b) => a.email.localeCompare(b.email));
+}
+
+function populateRoleTargetSelect(selectElement) {
+  if (!selectElement) {
+    return;
+  }
+
+  const users = getAssignableUsers();
+  const currentValue = selectElement.value;
+  selectElement.innerHTML = '<option value="">請選擇已核准用戶</option>';
+  users.forEach((user) => {
+    const option = document.createElement('option');
+    option.value = user.email;
+    option.textContent = `${user.company || '未提供公司'} / ${user.fullName || '未提供姓名'} / ${user.email}`;
+    if (user.email === currentValue) {
+      option.selected = true;
+    }
+    selectElement.appendChild(option);
+  });
+}
+
+function escapeCsvValue(value) {
+  const text = String(value ?? '');
+  if (/[",\n]/.test(text)) {
+    return `"${text.replace(/"/g, '""')}"`;
+  }
+  return text;
+}
+
+function downloadCsvFile(fileName, headers, rows) {
+  const lines = [headers.map(escapeCsvValue).join(',')];
+  rows.forEach((row) => {
+    lines.push(row.map(escapeCsvValue).join(','));
+  });
+
+  const bom = '\uFEFF';
+  const blob = new Blob([bom + lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
+  const link = document.createElement('a');
+  link.href = URL.createObjectURL(blob);
+  link.download = fileName;
+  document.body.appendChild(link);
+  link.click();
+  document.body.removeChild(link);
+  URL.revokeObjectURL(link.href);
+}
*** End Patch"}

